function createSpaceInvaders(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas || canvas.width !== 500 || canvas.height !== 500) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  let gameActive = true, level = 1, score = 0;
  const player = { x: W / 2 - 15, y: H - 40, w: 30, h: 20, speed: 7, bullets: [] };
  const invaders = [], invaderDirs = 1;
  const barrage = [], explosions = [];
  const keys = { left: false, right: false, fire: false };
  let lastEnemyFire = 0, enemySpeed = 1, enemyMoveTimer = 0, enemyMoveDelay = 2000;
  const invaderRows = 5, invaderCols = 8, invaderSpacing = 60, invaderXStart = 50, invaderYStart = 50;

  function drawRect(x, y, w, h, color) { ctx.fillStyle = color; ctx.fillRect(x, y, w, h); }
  function coll(a, b) { return ! (a.x + a.w < b.x || a.x > b.x + b.w || a.y + a.h < b.y || a.y > b.y + b.h); }

  function createInvaders() {
    invaders.length = 0;
    for (let r = 0; r < invaderRows; r++) {
      for (let c = 0; c < invaderCols; c++) {
        invaders.push({ x: invaderXStart + c * invaderSpacing, y: invaderYStart + r * invaderSpacing, w: 30, h: 20, alive: true });
      }
    }
  }
  createInvaders();

  function update(delta) {
    if (!gameActive) return;

    if (keys.left) player.x -= player.speed;
    if (keys.right) player.x += player.speed;
    if (player.x < 0) player.x = 0;
    if (player.x + player.w > W) player.x = W - player.w;

    if (keys.fire) {
      keys.fire = false;
      player.bullets.push({ x: player.x + player.w / 2 - 5, y: player.y, w: 10, h: 20, dy: -8 });
    }

    player.bullets.forEach((b, i) => {
      b.y += b.dy;
      if (b.y < 0) player.bullets.splice(i, 1);
    });

    barrage.forEach((b, i) => {
      b.y += b.dy;
      if (b.y > H) barrage.splice(i, 1);
    });

    if (Date.now() - lastEnemyFire > 2000) {
      const live = invaders.filter(i => i.alive);
      if (live.length) {
        const shooter = live[Math.floor(Math.random() * live.length)];
        barrage.push({ x: shooter.x + shooter.w / 2 - 5, y: shooter.y + shooter.h, w: 10, h: 20, dy: 6 });
        lastEnemyFire = Date.now();
      }
    }

    enemyMoveTimer += delta;
    if (enemyMoveTimer > enemyMoveDelay) {
      let changeDir = false;
      invaders.forEach(i => {
        if (i.alive) {
          i.x += invaderDirs * enemySpeed;
          if (i.x < 0 || i.x + i.w > W) changeDir = true;
        }
      });
      if (changeDir) {
        invaders.forEach(i => { if (i.alive) i.y += 20; });
        invaderDirs *= -1;
      }
      enemyMoveTimer = 0;
    }

    player.bullets.forEach((b, bi) => {
      invaders.forEach((inv, ii) => {
        if (inv.alive && coll(b, inv)) {
          inv.alive = false;
          player.bullets.splice(bi, 1);
          score += 10;
          explosions.push({ x: inv.x + inv.w / 2, y: inv.y + inv.h / 2, r: 0, life: 30 });
        }
      });
    });

    barrage.forEach((b, bi) => {
      if (coll(b, player)) {
        barrage.splice(bi, 1);
        gameActive = false;
        explosions.push({ x: player.x + player.w / 2, y: player.y + player.h / 2, r: 0, life: 30 });
        showMessage('GAME OVER');
      }
      invaders.forEach((inv, ii) => {
        if (inv.alive && coll(b, inv)) {
          inv.alive = false;
          barrage.splice(bi, 1);
          score += 15;
          explosions.push({ x: inv.x + inv.w / 2, y: inv.y + inv.h / 2, r: 0, life: 30 });
        }
      });
    });

    invaders.forEach(i => { if (i.alive && i.y + i.h > H - 30) { gameActive = false; showMessage('GAME OVER'); } });

    if (invaders.every(i => !i.alive)) {
      level++;
      enemySpeed += 0.2;
      createInvaders();
    }

    explosions.forEach((e, ei) => {
      e.r += 2;
      e.life--;
      if (e.life <= 0) explosions.splice(ei, 1);
    });
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    drawRect(player.x, player.y, player.w, player.h, '#0f0');
    player.bullets.forEach(b => drawRect(b.x, b.y, b.w, b.h, '#ff0'));
    barrage.forEach(b => drawRect(b.x, b.y, b.w, b.h, '#f00'));
    invaders.forEach(i => { if (i.alive) drawRect(i.x, i.y, i.w, i.h, '#00f'); });
    explosions.forEach(e => {
      ctx.strokeStyle = '#ffa500';
      ctx.beginPath(); ctx.arc(e.x, e.y, e.r, 0, Math.PI * 2); ctx.stroke();
    });
    ctx.fillStyle = '#fff';
    ctx.font = '20px Arial';
    ctx.fillText('Score: ' + score, 10, 30);
    ctx.fillText('Level: ' + level, 400, 30);
  }

  function showMessage(msg) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#fff';
    ctx.font = '40px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(msg, W / 2, H / 2);
  }

  let lastTime = 0;
  function loop(time) {
    const delta = time - lastTime;
    lastTime = time;
    update(delta);
    draw();
    if (gameActive) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') keys.left = true;
    if (e.key === 'ArrowRight') keys.right = true;
    if (e.key === ' ') keys.fire = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft') keys.left = false;
    if (e.key === 'ArrowRight') keys.right = false;
  });
}
